// Package payments charges invoices through the payment gateway.
package payments

import (
	"context"
	"errors"
	"fmt"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// ChargeRequest asks the gateway to take money from a payment method.
type ChargeRequest struct {
	Amount        int64 // minor units
	Currency      money.Currency
	PaymentMethod string // "pm_..."
	Description   string
}

// ChargeResult is a successful charge.
type ChargeResult struct {
	Ref string // the gateway's reference, "ch_..."
}

// Gateway is the payment processor.
type Gateway interface {
	Charge(ctx context.Context, req ChargeRequest) (ChargeResult, error)
}

// DeclineError is a charge the card's issuer refused. Nothing was taken.
type DeclineError struct {
	Code string // for example "card_declined", "insufficient_funds"
}

func (e *DeclineError) Error() string { return "card declined: " + e.Code }

// Errors.
var (
	// ErrUnavailable means the gateway could not be reached or failed; nothing was taken and the charge may be retried.
	ErrUnavailable     = errors.New("payment gateway unavailable")
	ErrAlreadyPaid     = errors.New("the invoice is already paid")
	ErrInvoiceVoid     = errors.New("the invoice is void")
	ErrNoPaymentMethod = errors.New("no payment method to charge")
)

// Publisher sends events to the organization's webhook endpoints (webhooks.Service).
type Publisher interface {
	Publish(ctx context.Context, orgID, eventType string, data any) error
}

// Service pays invoices.
type Service struct {
	Store     *store.Store
	Gateway   Gateway
	Clock     clock.Clock
	Publisher Publisher // nil: no events
}

// Pay charges an open invoice's total to paymentMethod, or to the customer's default payment method when it is empty, and
// marks the invoice paid. An invoice whose total is zero or less is marked paid without a charge. A declined charge is
// recorded as a failed payment and returned as a *DeclineError; when the gateway is unavailable nothing is recorded and the
// error wraps ErrUnavailable.
func (s *Service) Pay(ctx context.Context, orgID, invoiceID, paymentMethod string) (store.Invoice, store.Payment, error) {
	inv, ok := s.Store.Invoice(orgID, invoiceID)
	if !ok {
		return store.Invoice{}, store.Payment{}, store.ErrNotFound
	}
	switch inv.Status {
	case store.InvoicePaid:
		return inv, store.Payment{}, ErrAlreadyPaid
	case store.InvoiceVoid:
		return inv, store.Payment{}, ErrInvoiceVoid
	}
	total := billing.Compute(inv).Total
	if total <= 0 {
		inv, err := s.markPaid(ctx, inv, store.Payment{})
		return inv, store.Payment{}, err
	}
	if paymentMethod == "" {
		if c, ok := s.Store.Customer(orgID, inv.CustomerID); ok {
			paymentMethod = c.DefaultPaymentMethod
		}
	}
	if paymentMethod == "" {
		return inv, store.Payment{}, ErrNoPaymentMethod
	}
	res, err := s.Gateway.Charge(ctx, ChargeRequest{Amount: total, Currency: inv.Currency, PaymentMethod: paymentMethod, Description: "Invoice " + inv.ID})
	var decline *DeclineError
	switch {
	case errors.As(err, &decline):
		p, perr := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentFailed, FailureCode: decline.Code}, s.Clock.Now())
		if perr != nil {
			return inv, store.Payment{}, perr
		}
		s.publish(ctx, orgID, "invoice.payment_failed", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "failure_code": decline.Code})
		return inv, p, err
	case err != nil:
		if errors.Is(err, ErrUnavailable) {
			return inv, store.Payment{}, err
		}
		return inv, store.Payment{}, fmt.Errorf("%w: %v", ErrUnavailable, err)
	}
	p, err := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentSucceeded, GatewayRef: res.Ref}, s.Clock.Now())
	if err != nil {
		return inv, store.Payment{}, err
	}
	inv, err = s.markPaid(ctx, inv, p)
	return inv, p, err
}

func (s *Service) markPaid(ctx context.Context, inv store.Invoice, p store.Payment) (store.Invoice, error) {
	now := s.Clock.Now()
	inv, err := s.Store.UpdateInvoice(inv.OrgID, inv.ID, func(i *store.Invoice) error {
		i.Status = store.InvoicePaid
		i.PaidAt = &now
		return nil
	})
	if err != nil {
		return store.Invoice{}, err
	}
	s.publish(ctx, inv.OrgID, "invoice.paid", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "amount": p.Amount, "currency": inv.Currency})
	return inv, nil
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}
package store

import (
	"fmt"
	"sort"
)

// State is everything a store holds, for snapshots (package snapshot). Slices are sorted by ID.
type State struct {
	Seq              int               `json:"seq"`
	Orgs             []Org             `json:"orgs"`
	Users            []User            `json:"users"`
	Members          []Member          `json:"members"`
	APIKeys          []APIKey          `json:"api_keys"`
	Invites          []Invite          `json:"invites"`
	Customers        []Customer        `json:"customers"`
	Plans            []Plan            `json:"plans"`
	Subscriptions    []Subscription    `json:"subscriptions"`
	Usage            []UsageRecord     `json:"usage"`
	Invoices         []Invoice         `json:"invoices"`
	Payments         []Payment         `json:"payments"`
	WebhookEndpoints []WebhookEndpoint `json:"webhook_endpoints"`
	Events           []Event           `json:"events"`
	Deliveries       []Delivery        `json:"deliveries"`
}

// Export returns a copy of everything in the store.
func (s *Store) Export() State {
	s.mu.Lock()
	defer s.mu.Unlock()
	st := State{Seq: s.seq}
	for _, o := range s.orgs {
		st.Orgs = append(st.Orgs, o)
	}
	for _, u := range s.users {
		st.Users = append(st.Users, u)
	}
	for _, m := range s.members {
		st.Members = append(st.Members, m)
	}
	for _, k := range s.apiKeys {
		st.APIKeys = append(st.APIKeys, k)
	}
	for _, i := range s.invites {
		st.Invites = append(st.Invites, i)
	}
	for _, c := range s.customers {
		st.Customers = append(st.Customers, copyCustomer(c))
	}
	for _, p := range s.plans {
		st.Plans = append(st.Plans, p)
	}
	for _, sub := range s.subs {
		st.Subscriptions = append(st.Subscriptions, copySub(sub))
	}
	st.Usage = append(st.Usage, s.usage...)
	for _, inv := range s.invoices {
		st.Invoices = append(st.Invoices, copyInvoice(inv))
	}
	for _, p := range s.payments {
		st.Payments = append(st.Payments, p)
	}
	for _, ep := range s.endpoints {
		st.WebhookEndpoints = append(st.WebhookEndpoints, copyEndpoint(ep))
	}
	for _, e := range s.events {
		st.Events = append(st.Events, e)
	}
	for _, d := range s.delivs {
		st.Deliveries = append(st.Deliveries, copyDelivery(d))
	}
	sort.Slice(st.Orgs, func(i, j int) bool { return st.Orgs[i].ID < st.Orgs[j].ID })
	sort.Slice(st.Users, func(i, j int) bool { return st.Users[i].ID < st.Users[j].ID })
	sort.Slice(st.Members, func(i, j int) bool {
		if st.Members[i].OrgID != st.Members[j].OrgID {
			return st.Members[i].OrgID < st.Members[j].OrgID
		}
		return st.Members[i].UserID < st.Members[j].UserID
	})
	sort.Slice(st.APIKeys, func(i, j int) bool { return st.APIKeys[i].ID < st.APIKeys[j].ID })
	sort.Slice(st.Invites, func(i, j int) bool { return st.Invites[i].ID < st.Invites[j].ID })
	sort.Slice(st.Customers, func(i, j int) bool { return st.Customers[i].ID < st.Customers[j].ID })
	sort.Slice(st.Plans, func(i, j int) bool { return st.Plans[i].ID < st.Plans[j].ID })
	sort.Slice(st.Subscriptions, func(i, j int) bool { return st.Subscriptions[i].ID < st.Subscriptions[j].ID })
	sort.Slice(st.Usage, func(i, j int) bool { return st.Usage[i].ID < st.Usage[j].ID })
	sort.Slice(st.Invoices, func(i, j int) bool { return st.Invoices[i].ID < st.Invoices[j].ID })
	sort.Slice(st.Payments, func(i, j int) bool { return st.Payments[i].ID < st.Payments[j].ID })
	sort.Slice(st.WebhookEndpoints, func(i, j int) bool { return st.WebhookEndpoints[i].ID < st.WebhookEndpoints[j].ID })
	sort.Slice(st.Events, func(i, j int) bool { return st.Events[i].ID < st.Events[j].ID })
	sort.Slice(st.Deliveries, func(i, j int) bool { return st.Deliveries[i].ID < st.Deliveries[j].ID })
	return st
}

// FromState builds a store holding st.
func FromState(st State) (*Store, error) {
	s := New()
	s.seq = st.Seq
	dup := func(kind, id string, seen map[string]bool) error {
		if id == "" || seen[id] {
			return fmt.Errorf("%w: %s %q is missing or repeated", ErrInvalid, kind, id)
		}
		seen[id] = true
		return nil
	}
	seen := map[string]bool{}
	for _, o := range st.Orgs {
		if err := dup("organization", o.ID, seen); err != nil {
			return nil, err
		}
		s.orgs[o.ID] = o
	}
	for _, u := range st.Users {
		if err := dup("user", u.ID, seen); err != nil {
			return nil, err
		}
		s.users[u.ID] = u
		s.usersByEmail[normEmail(u.Email)] = u.ID
	}
	for _, m := range st.Members {
		if _, ok := s.orgs[m.OrgID]; !ok {
			return nil, fmt.Errorf("%w: member of unknown organization %q", ErrInvalid, m.OrgID)
		}
		if _, ok := s.users[m.UserID]; !ok {
			return nil, fmt.Errorf("%w: member is unknown user %q", ErrInvalid, m.UserID)
		}
		s.members[memberKey{m.OrgID, m.UserID}] = m
	}
	for _, k := range st.APIKeys {
		if err := dup("API key", k.ID, seen); err != nil {
			return nil, err
		}
		s.apiKeys[k.ID] = k
		if k.Token != "" {
			s.keysByToken[k.Token] = k.ID
		}
	}
	for _, i := range st.Invites {
		if err := dup("invite", i.ID, seen); err != nil {
			return nil, err
		}
		s.invites[i.ID] = i
	}
	for _, c := range st.Customers {
		if err := dup("customer", c.ID, seen); err != nil {
			return nil, err
		}
		s.customers[c.ID] = copyCustomer(c)
		s.customersByEmail[normEmail(c.Email)] = c.ID
	}
	for _, p := range st.Plans {
		if err := dup("plan", p.ID, seen); err != nil {
			return nil, err
		}
		s.plans[p.ID] = p
	}
	for _, sub := range st.Subscriptions {
		if err := dup("subscription", sub.ID, seen); err != nil {
			return nil, err
		}
		s.subs[sub.ID] = copySub(sub)
	}
	s.usage = append(s.usage, st.Usage...)
	for _, inv := range st.Invoices {
		if err := dup("invoice", inv.ID, seen); err != nil {
			return nil, err
		}
		s.invoices[inv.ID] = copyInvoice(inv)
	}
	for _, p := range st.Payments {
		if err := dup("payment", p.ID, seen); err != nil {
			return nil, err
		}
		s.payments[p.ID] = p
	}
	for _, ep := range st.WebhookEndpoints {
		if err := dup("webhook endpoint", ep.ID, seen); err != nil {
			return nil, err
		}
		s.endpoints[ep.ID] = copyEndpoint(ep)
	}
	for _, e := range st.Events {
		if err := dup("event", e.ID, seen); err != nil {
			return nil, err
		}
		s.events[e.ID] = e
	}
	for _, d := range st.Deliveries {
		if err := dup("delivery", d.ID, seen); err != nil {
			return nil, err
		}
		s.delivs[d.ID] = copyDelivery(d)
	}
	return s, nil
}
// Package snapshot saves the store to a JSON file and loads it back, so the server keeps its data across restarts. The
// file carries a version; files written by older versions of Tally are migrated when they are loaded.
package snapshot

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Version is the version Save writes.
const Version = 2

// ErrUnsupportedVersion is returned for a file of a version Load cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

type fileV2 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Save writes everything in st to path.
func Save(st *store.Store, path string, now time.Time) error {
	b, err := json.MarshalIndent(fileV2{Version: Version, SavedAt: now.UTC(), State: st.Export()}, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, append(b, '\n'), 0o600)
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return nil, fmt.Errorf("snapshot %s: %w", path, err)
	}
	var st store.State
	switch head.Version {
	case 1:
		if st, err = migrateV1(b); err != nil {
			return nil, fmt.Errorf("snapshot %s: version 1: %w", path, err)
		}
	case 2:
		var f fileV2
		if err := json.Unmarshal(b, &f); err != nil {
			return nil, fmt.Errorf("snapshot %s: %w", path, err)
		}
		st = f.State
	default:
		return nil, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, head.Version)
	}
	return store.FromState(st)
}

// Version 1 (Tally 0.x) kept the state at the top level. Organizations had no plan or time zone, customers had a
// full_name, and plans had a price in US cents (price_cents) and were all licensed.
type fileV1 struct {
	Seq           int                  `json:"seq"`
	Orgs          []orgV1              `json:"orgs"`
	Users         []store.User         `json:"users"`
	Members       []store.Member       `json:"members"`
	APIKeys       []store.APIKey       `json:"api_keys"`
	Customers     []customerV1         `json:"customers"`
	Plans         []planV1             `json:"plans"`
	Subscriptions []store.Subscription `json:"subscriptions"`
	Invoices      []store.Invoice      `json:"invoices"`
	Payments      []store.Payment      `json:"payments"`
}

type orgV1 struct {
	ID        string    `json:"id"`
	Name      string    `json:"name"`
	TaxRateBP int       `json:"tax_rate_bp"`
	CreatedAt time.Time `json:"created_at"`
}

type customerV1 struct {
	ID        string    `json:"id"`
	OrgID     string    `json:"org_id"`
	FullName  string    `json:"full_name"`
	Email     string    `json:"email"`
	CreatedAt time.Time `json:"created_at"`
}

type planV1 struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	PriceCents int64          `json:"price_cents"`
	Interval   store.Interval `json:"interval"`
	TrialDays  int            `json:"trial_days"`
	CreatedAt  time.Time      `json:"created_at"`
}

func migrateV1(b []byte) (store.State, error) {
	var f fileV1
	if err := json.Unmarshal(b, &f); err != nil {
		return store.State{}, err
	}
	st := store.State{Seq: f.Seq, Users: f.Users, Members: f.Members, APIKeys: f.APIKeys, Subscriptions: f.Subscriptions, Invoices: f.Invoices, Payments: f.Payments}
	for _, o := range f.Orgs {
		st.Orgs = append(st.Orgs, store.Org{ID: o.ID, Name: o.Name, Plan: store.OrgFree, TimeZone: "UTC", TaxRateBP: o.TaxRateBP, CreatedAt: o.CreatedAt})
	}
	for _, c := range f.Customers {
		st.Customers = append(st.Customers, store.Customer{ID: c.ID, OrgID: c.OrgID, Name: c.FullName, Email: c.Email, CreatedAt: c.CreatedAt})
	}
	for _, p := range f.Plans {
		st.Plans = append(st.Plans, store.Plan{ID: p.ID, OrgID: p.OrgID, Name: p.Name, Currency: money.USD, UnitAmount: p.PriceCents, Interval: p.Interval,
			UsageType: store.Licensed, TrialDays: p.TrialDays, Active: true, CreatedAt: p.CreatedAt})
	}
	return st, nil
}
// Package apitest builds a whole Tally service for tests: the store, a fake clock, the fake payment gateway, an email
// outbox, fake webhook receivers and DNS, the services and the API server, with two organizations to start from.
package apitest

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
	"time"

	"example.com/tally/internal/api"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/mail"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
	"example.com/tally/internal/webhooks"
)

// Start is the fake clock's time when an Env is created.
var Start = time.Date(2026, time.January, 15, 10, 0, 0, 0, time.UTC)

// Env is a running service and the fakes around it.
type Env struct {
	T        testing.TB
	Store    *store.Store
	Clock    *clock.Fake
	Gateway  *payments.Fake
	Mail     *mail.Outbox
	HTTP     *FakeHTTP // the organizations' webhook receivers
	DNS      *FakeDNS
	Webhooks *webhooks.Service
	Payments *payments.Service
	Subs     *subscriptions.Service
	Server   *api.Server

	// Acme (team plan, America/New_York) and Globex (business plan, Europe/Berlin) each have an owner with an API key.
	Acme, Globex Org
}

// Org is an organization with its owner and the owner's API key.
type Org struct {
	store.Org
	Owner store.User
	Key   string
}

// New builds a service for a test.
func New(t testing.TB) *Env {
	t.Helper()
	e := &Env{T: t, Store: store.New(), Clock: clock.NewFake(Start), Gateway: &payments.Fake{}, Mail: &mail.Outbox{}, HTTP: &FakeHTTP{}, DNS: &FakeDNS{}}
	e.DNS.Set("hooks.acme.example", "93.184.216.34")
	e.DNS.Set("hooks.globex.example", "93.184.216.35")
	e.Webhooks = webhooks.New(webhooks.Options{Store: e.Store, Clock: e.Clock, Doer: e.HTTP, Resolver: e.DNS})
	e.Payments = &payments.Service{Store: e.Store, Gateway: e.Gateway, Clock: e.Clock, Publisher: e.Webhooks}
	e.Subs = &subscriptions.Service{Store: e.Store, Payments: e.Payments, Clock: e.Clock, Publisher: e.Webhooks}
	e.Server = api.New(e.Store, api.Options{Clock: e.Clock, Payments: e.Payments, Subscriptions: e.Subs, Webhooks: e.Webhooks, Mail: e.Mail})
	e.Acme = e.NewOrg("Acme", store.OrgTeam, "America/New_York")
	e.Globex = e.NewOrg("Globex", store.OrgBusiness, "Europe/Berlin")
	return e
}

// NewOrg adds an organization with an owner (owner@<name>.example) and the owner's API key.
func (e *Env) NewOrg(name string, plan store.OrgPlan, timeZone string) Org {
	e.T.Helper()
	now := e.Clock.Now()
	o, err := e.Store.CreateOrg(name, plan, timeZone, 0, now)
	if err != nil {
		e.T.Fatalf("create org %s: %v", name, err)
	}
	u, err := e.Store.CreateUser("owner@"+strings.ToLower(name)+".example", name+" Owner", now)
	if err != nil {
		e.T.Fatalf("create owner of %s: %v", name, err)
	}
	if _, err := e.Store.AddMember(o.ID, u.ID, store.RoleOwner, now); err != nil {
		e.T.Fatal(err)
	}
	k, err := e.Store.CreateAPIKey(o.ID, u.ID, "Owner key", now)
	if err != nil {
		e.T.Fatal(err)
	}
	return Org{Org: o, Owner: u, Key: k.Token}
}

// AddMember adds a new user with this email address to org with a role, and returns them with an API key of theirs.
func (e *Env) AddMember(org Org, email string, role store.Role) (store.User, string) {
	e.T.Helper()
	now := e.Clock.Now()
	u, ok := e.Store.UserByEmail(email)
	if !ok {
		var err error
		if u, err = e.Store.CreateUser(email, strings.Split(email, "@")[0], now); err != nil {
			e.T.Fatal(err)
		}
	}
	if _, err := e.Store.AddMember(org.ID, u.ID, role, now); err != nil {
		e.T.Fatal(err)
	}
	k, err := e.Store.CreateAPIKey(org.ID, u.ID, "Key of "+email, now)
	if err != nil {
		e.T.Fatal(err)
	}
	return u, k.Token
}

// Response is the server's answer.
type Response struct {
	Code   int
	Header http.Header
	Body   []byte
}

// JSON decodes the body into v, failing the test when it cannot.
func (r *Response) JSON(t testing.TB, v any) {
	t.Helper()
	if err := json.Unmarshal(r.Body, v); err != nil {
		t.Fatalf("response %d is not the JSON expected: %v\n%s", r.Code, err, r.Body)
	}
}

// Map decodes the body as a JSON object.
func (r *Response) Map(t testing.TB) map[string]any {
	t.Helper()
	var m map[string]any
	r.JSON(t, &m)
	return m
}

// String is the status and body, for failure messages.
func (r *Response) String() string { return fmt.Sprintf("%d %s", r.Code, bytes.TrimSpace(r.Body)) }

// Do sends a request to the server with key as its API key ("" for none). A body that is a string or []byte is sent as it
// is; any other non-nil body is sent as JSON.
func (e *Env) Do(method, path, key string, body any) *Response {
	e.T.Helper()
	return e.DoWith(method, path, key, body, nil)
}

// DoWith is Do with extra request headers.
func (e *Env) DoWith(method, path, key string, body any, header http.Header) *Response {
	e.T.Helper()
	var rd io.Reader
	switch b := body.(type) {
	case nil:
	case string:
		rd = strings.NewReader(b)
	case []byte:
		rd = bytes.NewReader(b)
	default:
		raw, err := json.Marshal(b)
		if err != nil {
			e.T.Fatal(err)
		}
		rd = bytes.NewReader(raw)
	}
	req := httptest.NewRequest(method, path, rd)
	if key != "" {
		req.Header.Set("Authorization", "Bearer "+key)
	}
	for k, vs := range header {
		for _, v := range vs {
			req.Header.Add(k, v)
		}
	}
	rec := httptest.NewRecorder()
	e.Server.ServeHTTP(rec, req)
	return &Response{Code: rec.Code, Header: rec.Header(), Body: rec.Body.Bytes()}
}

// MustDo is Do that fails the test unless the answer has the status want, and decodes the body into out (when not nil).
func (e *Env) MustDo(want int, method, path, key string, body, out any) *Response {
	e.T.Helper()
	r := e.Do(method, path, key, body)
	if r.Code != want {
		e.T.Fatalf("%s %s: want %d, got %s", method, path, want, r)
	}
	if out != nil {
		r.JSON(e.T, out)
	}
	return r
}

// CreateCustomer creates a customer of org through the API.
func (e *Env) CreateCustomer(org Org, name, email string) store.Customer {
	e.T.Helper()
	var c store.Customer
	e.MustDo(http.StatusCreated, "POST", "/v1/customers", org.Key, map[string]string{"name": name, "email": email}, &c)
	return c
}

// CreatePlan creates a monthly licensed plan of org through the API, priced in major units ("12.50").
func (e *Env) CreatePlan(org Org, name, currency, price string) store.Plan {
	e.T.Helper()
	var p store.Plan
	e.MustDo(http.StatusCreated, "POST", "/v1/plans", org.Key, map[string]any{"name": name, "currency": currency, "price": price, "interval": "month"}, &p)
	return p
}

// ---- fakes

// FakeHTTP plays the organizations' webhook receivers: it records every request and answers 200, or what Respond returns
// when it is set (a status code, or an error for a request that never got an answer).
type FakeHTTP struct {
	// Respond, when set, answers each request. Set it before requests are made, or between them.
	Respond func(r Request) (int, error)

	mu       sync.Mutex
	requests []Request
}

// Request is a request a FakeHTTP received.
type Request struct {
	Method string
	URL    string
	Header http.Header
	Body   []byte
}

// Do implements webhooks.Doer.
func (f *FakeHTTP) Do(req *http.Request) (*http.Response, error) {
	var body []byte
	if req.Body != nil {
		body, _ = io.ReadAll(req.Body)
		req.Body.Close()
	}
	r := Request{Method: req.Method, URL: req.URL.String(), Header: req.Header.Clone(), Body: body}
	f.mu.Lock()
	f.requests = append(f.requests, r)
	respond := f.Respond
	f.mu.Unlock()
	status := http.StatusOK
	if respond != nil {
		var err error
		if status, err = respond(r); err != nil {
			return nil, err
		}
	}
	return &http.Response{StatusCode: status, Status: http.StatusText(status), Header: http.Header{}, Body: io.NopCloser(strings.NewReader("")), Request: req}, nil
}

// Requests returns the requests received so far, oldest first.
func (f *FakeHTTP) Requests() []Request {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]Request(nil), f.requests...)
}

// FakeDNS answers host lookups from the addresses Set gave it. Other hosts do not resolve.
type FakeDNS struct {
	mu    sync.Mutex
	hosts map[string][]string
}

// Set makes host resolve to ips (none: the host does not resolve).
func (d *FakeDNS) Set(host string, ips ...string) {
	d.mu.Lock()
	defer d.mu.Unlock()
	if d.hosts == nil {
		d.hosts = map[string][]string{}
	}
	d.hosts[strings.ToLower(host)] = ips
}

// LookupIPAddr implements webhooks.Resolver.
func (d *FakeDNS) LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error) {
	d.mu.Lock()
	ips := d.hosts[strings.ToLower(host)]
	d.mu.Unlock()
	if len(ips) == 0 {
		return nil, &net.DNSError{Err: "no such host", Name: host, IsNotFound: true}
	}
	out := make([]net.IPAddr, 0, len(ips))
	for _, s := range ips {
		ip := net.ParseIP(s)
		if ip == nil {
			return nil, fmt.Errorf("FakeDNS: %q is not an IP address", s)
		}
		out = append(out, net.IPAddr{IP: ip})
	}
	return out, nil
}
