		t.Fatalf("declined: %s", r)
	}
	if r := e.Do("POST", "/v1/invoices/"+first.ID+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_gateway_down"}); r.Code != http.StatusServiceUnavailable {
