// Ratio returns amount times part divided by whole, rounded half away from zero to a whole minor unit. It is exact for any
// int64 inputs, so the product cannot overflow. whole must be positive.
func Ratio(amount, part, whole int64) int64 {
	num := new(big.Int).Mul(big.NewInt(amount), big.NewInt(part))
	neg := num.Sign() < 0
	num.Abs(num)
	// floor(num/whole + 1/2) = floor((2*num + whole) / (2*whole)) for positive values.
	den := new(big.Int).Mul(big.NewInt(whole), big.NewInt(2))
	q := new(big.Int).Add(new(big.Int).Mul(num, big.NewInt(2)), big.NewInt(whole))
	q.Quo(q, den)
	if neg {
		q.Neg(q)
	}
	return q.Int64()
}

