func TestIncompatiblePlansAreRefused(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	euro := e.CreatePlan(e.Acme, "Euro", "EUR", "20.00")
	yearly, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Yearly", Currency: money.USD, UnitAmount: 20000, Interval: store.Yearly}, e.Clock.Now())
	metered, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Metered", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
	sub := subscribe(t, e, "pm_card_visa", team, 1)

	for _, p := range []store.Plan{euro, yearly, metered} {
		if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, setPlan(p.ID)); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
			t.Fatalf("change to %s: %v, want ErrIncompatiblePlan", p.Name, err)
		}
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.PlanID != team.ID {
		t.Fatalf("a refused change applied: %+v", got)
	}
}

