+		if err != nil {
+			t.Fatal(err)
+		}
+		if got.PlanID != pro.ID || got.PendingPlanID != nil || got.PendingQuantity != nil {
+			t.Fatalf("subscription = %+v", got)
+		}
+		if n := len(invoicesOf(e, sub.ID)); n != 1 {
+			t.Fatalf("a revert billed: %d invoices", n)
+		}
+	})
+
+	t.Run("upgrade", func(t *testing.T) {
+		e := apitest.New(t)
+		team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
+		pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
+		sub := subscribe(t, e, "pm_card_visa", pro, 2)
+		e.Clock.Set(e.Clock.Now().AddDate(0, 0, 10))
+		if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, setPlan(team.ID)); err != nil {
+			t.Fatal(err)
+		}
+		got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, setQty(4))
+		if err != nil {
+			t.Fatal(err)
+		}
+		if got.PlanID != pro.ID || got.Quantity != 4 || got.PendingPlanID != nil || got.PendingQuantity != nil {
+			t.Fatalf("subscription = %+v", got)
+		}
+		if n := len(invoicesOf(e, sub.ID)); n != 2 {
+			t.Fatalf("the upgrade was not billed: %d invoices", n)
+		}
+	})
+}
+
+func TestEqualValueChangeAppliesWithoutBilling(t *testing.T) {
